-- Shared Auth schema: clients, users, profiles, external identities,
-- login attempts, authorization codes, sessions, roles, user roles,
-- and rotating refresh tokens.
--
-- Placed in dedicated 'auth' schema for single-DB multi-tenant/service isolation.
-- All primary keys are UUIDv7 values generated by the application; no
-- database-side default is used.

CREATE SCHEMA IF NOT EXISTS auth;

-- Set search_path for the migration session
SET search_path TO auth, public;

-- Each row is one OAuth app registration at one provider (Google/GitHub) for
-- one website, identified by the provider-issued client_id. A website using
-- both providers has two rows. client_secret_enc is the provider's OAuth app
-- secret (encrypted); auth_secret_hash authenticates the website's own
-- backend calling this service, separate from the provider secret.
-- Web registration holds a backend secret hash; mobile (public client)
-- authenticates via PKCE alone.
CREATE TABLE auth.clients (
    id                 UUID PRIMARY KEY,
    provider           VARCHAR(32) NOT NULL,
    client_id          VARCHAR(255) NOT NULL,
    client_secret_enc  TEXT NOT NULL,
    auth_secret_hash   VARCHAR(255),
    client_type        VARCHAR(16) NOT NULL DEFAULT 'web',
    name               VARCHAR(255) NOT NULL,
    redirect_url       TEXT NOT NULL,
    redirect_uris      TEXT[] NOT NULL,
    enabled            BOOLEAN NOT NULL DEFAULT true,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, client_id),
    CONSTRAINT clients_client_type_check
        CHECK (client_type IN ('web', 'mobile')),
    CONSTRAINT clients_auth_secret_by_type_check
        CHECK (
            (client_type = 'web' AND auth_secret_hash IS NOT NULL) OR
            (client_type = 'mobile' AND auth_secret_hash IS NULL)
        )
);

CREATE TABLE auth.users (
    id              UUID PRIMARY KEY,
    canonical_email VARCHAR(255) UNIQUE
);

CREATE TABLE auth.roles (
    id         UUID PRIMARY KEY,
    key        VARCHAR(64) NOT NULL UNIQUE,
    name       VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE auth.user_roles (
    user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    role_id    UUID NOT NULL REFERENCES auth.roles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);

CREATE INDEX user_roles_role_id_idx ON auth.user_roles (role_id);

CREATE TABLE auth.profiles (
    user_id               UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    display_name          VARCHAR(255),
    avatar_url            TEXT,
    display_name_managed  BOOLEAN NOT NULL DEFAULT false,
    avatar_url_managed    BOOLEAN NOT NULL DEFAULT false,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE auth.external_identities (
    id               UUID PRIMARY KEY,
    user_id          UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    provider         VARCHAR(32) NOT NULL,
    provider_subject VARCHAR(255) NOT NULL,
    email            VARCHAR(255),
    email_verified   BOOLEAN NOT NULL DEFAULT false,
    display_name     VARCHAR(255),
    avatar_url       TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, provider_subject)
);

CREATE INDEX external_identities_user_id_idx ON auth.external_identities (user_id);

CREATE TABLE auth.login_attempts (
    id                    UUID PRIMARY KEY,
    client_ref            UUID NOT NULL REFERENCES auth.clients(id) ON DELETE CASCADE,
    provider              VARCHAR(32) NOT NULL,
    state                 VARCHAR(255) NOT NULL UNIQUE,
    nonce                 VARCHAR(255) NOT NULL,
    code_challenge        VARCHAR(255) NOT NULL,
    code_challenge_method VARCHAR(32) NOT NULL DEFAULT 'S256',
    redirect_uri          TEXT NOT NULL,
    product_state         TEXT NOT NULL,
    expires_at            TIMESTAMPTZ NOT NULL,
    consumed_at           TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE auth.auth_codes (
    id                    UUID PRIMARY KEY,
    code                  VARCHAR(255) NOT NULL UNIQUE,
    client_ref            UUID NOT NULL REFERENCES auth.clients(id) ON DELETE CASCADE,
    user_id               UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    identity_id           UUID NOT NULL REFERENCES auth.external_identities(id) ON DELETE CASCADE,
    redirect_uri          TEXT NOT NULL,
    code_challenge        VARCHAR(255) NOT NULL,
    code_challenge_method VARCHAR(32) NOT NULL DEFAULT 'S256',
    expires_at            TIMESTAMPTZ NOT NULL,
    consumed_at           TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX auth_codes_user_id_idx ON auth.auth_codes (user_id);
CREATE INDEX auth_codes_identity_id_idx ON auth.auth_codes (identity_id);

-- Immutable snapshot of the registration's type at session creation, so
-- the session/admin API can report it without joining clients.
CREATE TABLE auth.sessions (
    id          UUID PRIMARY KEY,
    user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    identity_id UUID NOT NULL REFERENCES auth.external_identities(id) ON DELETE CASCADE,
    client_ref  UUID NOT NULL REFERENCES auth.clients(id) ON DELETE CASCADE,
    client_type VARCHAR(16) NOT NULL DEFAULT 'web',
    expires_at  TIMESTAMPTZ NOT NULL,
    revoked_at  TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX sessions_user_id_idx ON auth.sessions (user_id);
CREATE INDEX sessions_identity_id_idx ON auth.sessions (identity_id);

-- Rotating refresh tokens alongside session JWT.
CREATE TABLE auth.refresh_tokens (
    id          UUID PRIMARY KEY,
    session_id  UUID NOT NULL REFERENCES auth.sessions(id) ON DELETE CASCADE,
    token_hash  VARCHAR(64) NOT NULL UNIQUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    consumed_at TIMESTAMPTZ
);

CREATE INDEX refresh_tokens_session_id_idx ON auth.refresh_tokens (session_id);

-- At most one unconsumed (live) refresh token per session: the current
-- generation of its rotation family.
CREATE UNIQUE INDEX refresh_tokens_session_unconsumed_idx
    ON auth.refresh_tokens (session_id)
    WHERE consumed_at IS NULL;
